import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    Color,
  } = THREE;

  const root = new Group();
  const timelines = [];
  const resources = [];
  let disposed = false;

  root.userData.handlers = {};

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: false,
  });

  surfaceMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.08, 0.92, uv().y),
  );

  const surfaceGeometry = new PlaneGeometry(5.05, 3.16);
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.z = -0.08;
  root.add(surface);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 1,
  });

  const imageGeometry = new PlaneGeometry(4.8, 3);
  const image = new Mesh(imageGeometry, imageMaterial);
  image.position.z = 0.01;
  root.add(image);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: false,
  });

  const accentVertical = new Mesh(
    new PlaneGeometry(0.055, 1.7),
    accentMaterial,
  );
  accentVertical.position.set(2.28, 0.35, 0.045);
  root.add(accentVertical);

  const accentHorizontal = new Mesh(
    new PlaneGeometry(0.72, 0.045),
    accentMaterial,
  );
  accentHorizontal.position.set(-1.72, -1.28, 0.045);
  root.add(accentHorizontal);

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) root.quaternion.copy(camera.quaternion);
  };

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl)
      .then((texture) => {
        if (disposed) {
          texture.dispose();
          return;
        }

        const atlasWidth = texture.image?.width || 512;
        const atlasHeight = texture.image?.height || 320;
        const source = config.atlasRegion ?? {
          x: 0,
          y: 0,
          width: 512,
          height: 320,
        };

        texture.wrapS = THREE.ClampToEdgeWrapping;
        texture.wrapT = THREE.ClampToEdgeWrapping;
        texture.repeat.set(
          source.width / atlasWidth,
          source.height / atlasHeight,
        );
        texture.offset.set(
          source.x / atlasWidth,
          1 - ((source.y + source.height) / atlasHeight),
        );
        texture.needsUpdate = true;

        if ('colorSpace' in texture && THREE.SRGBColorSpace) {
          texture.colorSpace = THREE.SRGBColorSpace;
        }

        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
        resources.push(texture);
      })
      .catch(() => {});
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    root.onBeforeRender = null;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    surfaceGeometry.dispose();
    imageGeometry.dispose();
    accentVertical.geometry.dispose();
    accentHorizontal.geometry.dispose();

    surfaceMaterial.dispose();
    imageMaterial.dispose();
    accentMaterial.dispose();
  };

  return root;
}
